var studentRecords = [];

// Safe UTF-8 Base64 Decoder that will NOT crash or freeze
function getDecodedData() {
  if (studentRecords && studentRecords.length > 0) {
    return studentRecords;
  }
  
  if (typeof encodedString === "undefined" || !encodedString) {
    console.error("encodedString is not defined!");
    return [];
  }

  try {
    // Method 1: Fast Uint8Array + TextDecoder (Handles UTF-8 Bengali/English cleanly)
    var binary = window.atob(encodedString);
    var bytes = new Uint8Array(binary.length);
    for (var i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    studentRecords = JSON.parse(new TextDecoder("utf-8").decode(bytes));
    return studentRecords;
  } catch (err1) {
    try {
      // Method 2: Standard fallback
      studentRecords = JSON.parse(window.atob(encodedString));
      return studentRecords;
    } catch (err2) {
      console.error("Fatal error decoding student data:", err2);
      return [];
    }
  }
}

// Result search function
function showResult() {
  try {
    var nameInput = document.getElementById("inputValueName");
    var rollInput = document.getElementById("inputValue");
    var resultDisplay = document.getElementById("resultDisplay");
    var downloadBtn = document.getElementById("downloadCertBtn");

    if (!resultDisplay) {
      alert("Error: 'resultDisplay' element is missing in HTML.");
      return;
    }

    var nameVal = nameInput ? nameInput.value.trim().toUpperCase() : "";
    var rollVal = rollInput ? rollInput.value.trim().toUpperCase() : "";

    // Validation check
    if (!nameVal || !rollVal) {
      resultDisplay.style.display = "block";
      resultDisplay.style.backgroundColor = "#ffdddd";
      resultDisplay.style.color = "#a00000";
      resultDisplay.innerText = "Please enter both your Full Name and Roll Number.";
      if (downloadBtn) downloadBtn.style.display = "none";
      return;
    }

    // Load data safely
    var data = getDecodedData();
    if (!data || data.length === 0) {
      resultDisplay.style.display = "block";
      resultDisplay.style.backgroundColor = "#ffdddd";
      resultDisplay.style.color = "#a00000";
      resultDisplay.innerText = "Error: Student database could not be loaded. Please check cScript-2026.js.";
      return;
    }

    // Flexible student lookup
    var student = data.find(function(item) {
      var itemRoll = String(item["RollNumber"] || item["Roll No"] || "").trim().toUpperCase();
      var itemName = String(item["Name"] || "").trim().toUpperCase();

      // Normalize multiple spaces
      var cleanInputName = nameVal.replace(/\s+/g, ' ');
      var cleanDbName = itemName.replace(/\s+/g, ' ');

      // Match roll number and check if input name is inside DB name (or DB name in input)
      var rollMatch = (itemRoll === rollVal);
      var nameMatch = cleanDbName.indexOf(cleanInputName) !== -1 || cleanInputName.indexOf(cleanDbName) !== -1;

      return rollMatch && nameMatch;
    });

    if (student) {
      var marks = student["Marks"] !== undefined ? student["Marks"] : "N/A";
      var studentClass = student["Class"] || "N/A";
      var schoolName = student["SCHOOLNAME"] || "N/A";
      var guardianName = student["GUARDIAN'SNAME"] || "N/A";

      // Show result box
      resultDisplay.style.display = "block";
      resultDisplay.style.backgroundColor = "#d4edda";
      resultDisplay.style.color = "#155724";
      resultDisplay.innerHTML =
        "<h4 style='margin-bottom:8px; font-weight:bold; color:#155724;'>Result Found!</h4>" +
        "<div><b>Name:</b> " + student["Name"] + "</div>" +
        "<div><b>Roll Number:</b> " + student["RollNumber"] + "</div>" +
        "<div><b>Class:</b> " + studentClass + "</div>" +
        "<div><b>School:</b> " + schoolName + "</div>" +
        "<div><b>Guardian:</b> " + guardianName + "</div>" +
        "<div style='font-size:16px; margin-top:5px;'><b>Marks Obtained:</b> <span style='color:#0f2b48; font-weight:bold;'>" + marks + "</span></div>";

      // Prepare Certificate Download link with query parameters
      if (downloadBtn) {
        var query = "?name=" + encodeURIComponent(student["Name"]) +
                    "&roll=" + encodeURIComponent(student["RollNumber"]) +
                    "&class=" + encodeURIComponent(studentClass) +
                    "&school=" + encodeURIComponent(schoolName) +
                    "&guardian=" + encodeURIComponent(guardianName) +
                    "&marks=" + encodeURIComponent(marks);

        downloadBtn.href = "certificate.html" + query;
        downloadBtn.style.display = "inline-block";
      }

      // Also set localStorage & sessionStorage
      try {
        var payload = JSON.stringify(student);
        localStorage.setItem("currentStudentCert", payload);
        sessionStorage.setItem("currentStudentCert", payload);
      } catch (e) {}

    } else {
      // Student not found
      resultDisplay.style.display = "block";
      resultDisplay.style.backgroundColor = "#fff3cd";
      resultDisplay.style.color = "#856404";
      resultDisplay.innerText = "No student record found matching Roll: '" + rollVal + "' and Name: '" + nameVal + "'. Please check spelling and roll number format.";
      if (downloadBtn) downloadBtn.style.display = "none";
    }
  } catch (globalErr) {
    console.error("showResult error:", globalErr);
    alert("An error occurred: " + globalErr.message);
  }
}
